{"content":"<?php

namespace Tests\Feature;

use App\Enums\EnrollmentStatus;
use App\Enums\GradeType;
use App\Enums\Role;
use App\Models\Course;
use App\Models\CourseEnrollment;
use App\Models\Grade;
use App\Models\Setting;
use App\Models\Student;
use App\Models\User;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Livewire\Livewire;
use Tests\TestCase;

/*
|---------------------------------------------------------------------------
| کارنامهٔ رسمی (شماره 37)
|
| R4 می‌گوید سند باید قابل چاپ و PDF باشد و شمارهٔ سند، امضا و تاریخ شمسی
| داشته باشد. چهار چیز باید این‌جا اثبات شود:
|   ۱. سند بدون منوی پنل چاپ می‌شود و سربرگ آموزشگاه، ریزنمرات، جمع/میانگین،
|      ساعت، وضعیت قبولی و محل امضا دارد.
|   ۲. دانش‌آموز بدون نمره هم سند می‌گیرد — با «فاقد سابقه». سندِ صادرنشدنی
|      برای کسی که هنوز امتحان نداده یعنی پروندهٔ ناقص در آرشیو.
|   ۳. قبولی/مردود از نمرهٔ قبولیِ تنظیمات درمی‌آید، نه از عددی که در کد
|      جا افتاده باشد.
|   ۴. مجوز در لایهٔ route است: پنهان‌کردن لینک امنیت نیست.
|
| تاریخ‌ها همه شمسی‌اند و با to_persian_digits نمایش داده می‌شوند چون
| jalali_date ارقام لاتین برمی‌گرداند.
*/

class TranscriptTest extends TestCase
{
    use RefreshDatabase;

    private function actingAsRole(Role $role): User
    {
        $user = User::factory()->role($role)->create();

        $this->actingAs($user);

        return $user;
    }

    /** دانش‌آموزِ ثبت‌نام‌شدهٔ قطعی در یک دوره. */
    private function enrolled(array $courseAttributes = []): array
    {
        $course = Course::factory()->create($courseAttributes);
        $student = Student::factory()->create();

        CourseEnrollment::enroll($student, $course)->confirm();

        return [$student, $course];
    }

    // ── صدور سند ───────────────────────────────────────────

    public function test_the_transcript_is_a_printable_sheet_without_the_panel_chrome(): void
    {
        $this->actingAsRole(Role::Admin);
        [$student, $course] = $this->enrolled();
        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 18);

        $response = $this->get(route('students.transcript', $student));

        $response->assertOk();
        // منو و سایهٔ پنل روی کاغذ نباید بیفتند
        $response->assertDontSee('drawer');

        $response->assertSee('کارنامه رسمی')
            ->assertSee(Setting::academyName())
            ->assertSee($student->first_name)
            ->assertSee($course->title)
            ->assertSee('امضای مدیر آموزشگاه');
    }

    public function test_the_transcript_breaks_the_grades_down_by_type(): void
    {
        $this->actingAsRole(Role::Deputy);
        [$student, $course] = $this->enrolled();

        Grade::record($student, $course, GradeType::Homework, 'تکلیف اول', 18);
        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 15);

        $response = $this->get(route('students.transcript', $student));

        $response->assertOk()
            ->assertSee('ریزنمرات')
            ->assertSee('تکلیف')
            ->assertSee('پایان‌ترم')
            // نمرهٔ خامِ هر ردیف با مخرجش، نه فقط درصد
            ->assertSee(to_persian_digits(number_format(18, 2)).'/'.to_persian_digits(number_format(20, 2)))
            ->assertSee(to_persian_digits(number_format(15, 2)).'/'.to_persian_digits(number_format(20, 2)));
    }

    public function test_the_transcript_carries_the_totals_the_average_and_the_pass_status(): void
    {
        $this->actingAsRole(Role::Admin);
        [$student, $course] = $this->enrolled(['session_count' => 11, 'session_duration' => 180]);

        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 16);
        Grade::record($student, $course, GradeType::Homework, 'تکلیف اول', 20);

        $response = $this->get(route('students.transcript', $student));

        // نمرهٔ نهایی: میانگین وزنیِ درصدها → ۹۰٪ → ۱۸ از ۲۰
        $response->assertOk()
            ->assertSee('جمع ساعات')
            ->assertSee('میانگین کل')
            ->assertSee(to_persian_digits(number_format(18, 2)))
            ->assertSee('قبولی');
    }

    // ── دانش‌آموز بدون نمره ────────────────────────────────

    public function test_a_student_without_any_grade_still_gets_a_document(): void
    {
        $this->actingAsRole(Role::Admin);
        [$student] = $this->enrolled();

        // نباید exception بدهد و نباید سند بی‌سند صادر شود
        $response = $this->get(route('students.transcript', $student));

        $response->assertOk()
            ->assertSee('کارنامه رسمی')
            ->assertSee('فاقد سابقه')
            ->assertDontSee('مردود')
            ->assertDontSee('قبولی');
    }

    public function test_a_student_with_no_enrollment_gets_an_empty_but_valid_document(): void
    {
        $this->actingAsRole(Role::Admin);
        $student = Student::factory()->create();

        $this->get(route('students.transcript', $student))
            ->assertOk()
            ->assertSee('هیچ دوره‌ای')
            ->assertSee('فاقد سابقه');
    }

    // ── قبولی و مردودی ────────────────────────────────────

    public function test_pass_and_fail_follow_the_passing_score_setting(): void
    {
        $this->actingAsRole(Role::Admin);

        [$passing] = $this->enrolled();
        Grade::record($passing, $this->courseOf($passing), GradeType::Final, 'پایان‌ترم', 18);

        [$failing] = $this->enrolled();
        Grade::record($failing, $this->courseOf($failing), GradeType::Final, 'پایان‌ترم', 6);

        $this->get(route('students.transcript', $passing))->assertSee('قبولی');
        $this->get(route('students.transcript', $failing))->assertSee('مردود');

        // نمرهٔ قبولی قابل تنظیم است و با ارقام فارسی هم وارد می‌شود
        Setting::put(Setting::PASSING_SCORE, '۱۹');

        $this->get(route('students.transcript', $passing))->assertSee('مردود');
    }

    // ── شمارهٔ سند، تاریخ و ساعت ──────────────────────────

    public function test_the_document_carries_a_number_a_shamsi_date_and_the_hours(): void
    {
        $this->actingAsRole(Role::Admin);
        [$student, $course] = $this->enrolled(['session_count' => 11, 'session_duration' => 180]);
        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 15);

        $response = $this->get(route('students.transcript', $student));

        // ۱۱ جلسهٔ ۱۸۰ دقیقه‌ای = ۳۳ ساعت
        $response->assertOk()
            ->assertSee('شماره سند')
            ->assertSee('TR-'.to_persian_digits(jalali_date(now(), 'Ymd')).'-'.to_persian_digits($student->id))
            ->assertSee(to_persian_digits(jalali_date(now())))
            ->assertSee(to_persian_digits($course->totalHours()).' ساعت');
    }

    public function test_the_transcript_numbers_only_the_courses_that_are_confirmed(): void
    {
        $this->actingAsRole(Role::Admin);
        [$student, $course] = $this->enrolled();
        Grade::record($student, $course, GradeType::Final, 'پایان‌ترم', 15);

        // ثبت‌نام لغوشده روی کارنامه نمی‌آید
        $cancelled = Course::factory()->create();
        CourseEnrollment::enroll($student, $cancelled)->confirm()->cancel();

        $response = $this->get(route('students.transcript', $student));

        $response->assertOk()
            ->assertSee($course->title)
            ->assertDontSee($cancelled->title);
    }

    // ── دسترسی ────────────────────────────────────────────

    public function test_only_admin_and_deputy_may_open_a_transcript(): void
    {
        $student = Student::factory()->create();

        $this->get(route('students.transcript', $student))->assertRedirect(route('login'));

        foreach ([Role::Finance, Role::Teacher, Role::Reception] as $role) {
            $this->actingAsRole($role)
                ->get(route('students.transcript', $student))
                ->assertForbidden();
        }

        foreach ([Role::Admin, Role::Deputy] as $role) {
            $this->actingAsRole($role)
                ->get(route('students.transcript', $student))
                ->assertOk();
        }
    }

    public function test_the_student_file_links_to_the_transcript_only_for_roles_that_may_issue_it(): void
    {
        [$student] = $this->enrolled();

        $this->actingAsRole(Role::Admin);

        Livewire::test('pages::students.show', ['student' => $student->id])
            ->assertSee(route('students.transcript', $student));

        // امور مالی پرونده را برای بدهی باز می‌کند، نه برای صدور کارنامه
        $this->actingAsRole(Role::Finance);

        Livewire::test('pages::students.show', ['student' => $student->id])
            ->assertDontSee(route('students.transcript', $student));
    }

    /** دوره‌ای که این دانش‌آموز در آن ثبت‌نام قطعی دارد. */
    private function courseOf(Student $student): Course
    {
        return $student->enrollments()
            ->where('status', EnrollmentStatus::Confirmed->value)
            ->firstOrFail()
            ->course;
    }
}
