{"content":"<?php

namespace App\Services;

use App\Enums\EnrollmentStatus;
use App\Enums\GradeType;
use App\Models\Course;
use App\Models\Grade;
use App\Models\Setting;
use App\Models\Student;
use Illuminate\Support\Collection;

/**
 * دادهٔ کارنامهٔ رسمی یک دانش‌آموز (شماره 37).
 *
 * این سازندهٔ «سند» است نه گزارش: خروجی باید همان چیزی باشد که روی کاغذ
 * می‌رود — ریزنمرات، جمع ساعت، میانگین، وضعیت قبولی و شمارهٔ سند — و نباید
 * چیزی را که ندارد «صفر» کند. دانش‌آموز بدون نمره سند می‌گیرد با «فاقد
 * سابقه»، چون سندِ صادرنشدنی یعنی پروندهٔ ناقص در آرشیو.
 *
 * نمرهٔ نهایی و رتبه از WeightedAverage می‌آیند، نه از میانگین سادهٔ نمره‌ها:
 * کارنامه باید با صفحهٔ نمرات یک عدد بدهد.
 */
class TranscriptBuilder
{
    public function __construct(
        private readonly WeightedAverage $average = new WeightedAverage,
    ) {}

    /**
     * @return array{
     *     student: Student,
     *     rows: Collection<int, array>,
     *     summary: array,
     *     document: array,
     * }
     */
    public function build(Student $student): array
    {
        $rows = $student->enrollments()
            ->where('status', EnrollmentStatus::Confirmed->value)
            ->with(['course.subject', 'course.teacher'])
            ->get()
            ->map(fn ($enrollment) => $this->row($student, $enrollment->course))
            ->values();

        return [
            'student' => $student,
            'rows' => $rows,
            'summary' => $this->summary($rows),
            'document' => $this->document($student),
        ];
    }

    /** یک ردیف کارنامه: دوره، ریزنمرات، نمرهٔ نهایی، رتبه و وضعیت. */
    private function row(Student $student, Course $course): array
    {
        $grades = Grade::forStudentInCourse($student, $course)
            ->sortBy([['type', 'asc'], ['title', 'asc']])
            ->values();

        $score = $this->average->finalScore($student, $course);

        return [
            'course' => $course,
            'grades' => $grades,
            'breakdown' => $this->breakdown($grades),
            'score' => $score,
            'rank' => $this->rank($student, $course),
            'status' => $this->status($grades, $score),
            'hours' => $course->totalHours(),
            'hours_label' => $this->hoursLabel($course->totalHours()),
        ];
    }

    /**
     * ریزنمرات به تفکیک نوع نمره.
     *
     * میانگین درصد می‌آید نه میانگین نمرهٔ خام: تکلیف ۱۰نمره‌ای و پایان‌ترم
     * ۲۰نمره‌ای اگر خام میانگین شوند، نمرهٔ بالاترِ پایان‌ترم بی‌بهانه وزن
     * بیشتری پیدا می‌کند.
     *
     * @param  Collection<int, Grade>  $grades
     * @return Collection<int, array>
     */
    private function breakdown(Collection $grades): Collection
    {
        return $grades
            ->groupBy(fn (Grade $grade) => $grade->type->value)
            ->map(function (Collection $group, string $typeValue) {
                $type = GradeType::tryFrom($typeValue);
                $percent = $group->sum(fn (Grade $grade) => $grade->percentage()) / $group->count();

                return [
                    'type' => $type,
                    'label' => $type?->label() ?? '—',
                    'count' => $group->count(),
                    'percent' => round($percent, 2),
                    'score' => round($percent * 20 / 100, 2),
                ];
            })
            ->values();
    }

    /** رتبه در میان ثبت‌نام‌های قطعی همان دوره؛ بدون نمره رتبه ندارد. */
    private function rank(Student $student, Course $course): ?int
    {
        $row = $this->average->rankStudents($course)->firstWhere('student.id', $student->id);

        return $row['rank'] ?? null;
    }

    /**
     * وضعیت قبولی یک دوره.
     *
     * «فاقد سابقه» یعنی اصلاً نمره‌ای ثبت نشده — نه نمرهٔ صفر. صفرکردنِ
     * نبودِ داده، دانش‌آموزی را که هنوز امتحان نداده مردود نشان می‌دهد.
     *
     * @param  Collection<int, Grade>  $grades
     */
    private function status(Collection $grades, ?float $score): string
    {
        if ($grades->isEmpty()) {
            return 'فاقد سابقه';
        }

        if ($score === null) {
            return 'فاقد نمرهٔ نهایی';
        }

        return $score >= Setting::passingScore() ? 'قبولی' : 'مردود';
    }

    /** @param  Collection<int, array>  $rows */
    private function summary(Collection $rows): array
    {
        $scores = $rows->pluck('score')->filter(fn ($score) => $score !== null);

        return [
            'hours' => $rows->sum('hours'),
            'hours_label' => $this->hoursLabel($rows->sum('hours')),
            'average' => $scores->isEmpty() ? null : round($scores->avg(), 2),
            'courses' => $rows->count(),
            'passed' => $rows->where('status', 'قبولی')->count(),
            'failed' => $rows->where('status', 'مردود')->count(),
            'unknown' => $rows->where('status', 'فاقد سابقه')->count(),
        ];
    }

    /**
     * شمارهٔ سند و تاریخ صدور.
     *
     * شماره از شناسهٔ دانش‌آموز و تاریخِ صدور ساخته می‌شود، نه از یک جدول
     * شماره‌ساز: چاپِ دوبارهٔ همان سند باید همان شماره را بدهد، و شمارهٔ
     * پیاپیِ تازه برای هر بار چاپ یعنی دو «سند متفاوت» با یک محتوا.
     *
     * @return array{number: string, issued_on: string, passing: float}
     */
    private function document(Student $student): array
    {
        return [
            'number' => 'TR-'.to_persian_digits(jalali_date(now(), 'Ymd'))
                .'-'.to_persian_digits($student->id),
            'issued_on' => to_persian_digits(jalali_date(now())),
            'passing' => Setting::passingScore(),
        ];
    }

    /** ساعت کسرشده از ممیز اضافه نمایش داده می‌شود: «۳۳» بهتر از «۳۳٫۰». */
    private function hoursLabel(float $hours): string
    {
        $label = number_format($hours, 1);

        if (str_ends_with($label, '.0')) {
            $label = substr($label, 0, -2);
        }

        return to_persian_digits($label);
    }
}
